import { completionStatus } from "@codemirror/autocomplete";
import {
  copyLineDown,
  copyLineUp,
  defaultKeymap,
  history,
  historyKeymap,
  moveLineDown,
  moveLineUp,
} from "@codemirror/commands";
import { syntaxHighlighting } from "@codemirror/language";
import {
  Annotation,
  Compartment,
  EditorState,
  Prec,
  type Extension,
} from "@codemirror/state";
import {
  EditorView,
  keymap,
  placeholder as placeholderExtension,
  tooltips,
} from "@codemirror/view";
import { classHighlighter } from "@lezer/highlight";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  type CSSProperties,
  type ReactNode,
} from "react";

import { grammarExtensions, type CodeFieldGrammar } from "./codeGrammar";
import { CodeFieldRows } from "./codeFieldRows";
import { FieldGesture } from "./fieldGesture";

/** Marks the field's own imperative doc swaps so the change listener never echoes them back as typing. */
const externalSync = Annotation.define<boolean>();

export interface CodeFieldProps {
  /** The value. The field follows it whenever nobody is editing. */
  value: string;
  /** Write, per keystroke — the field's one write policy (see `fieldGesture.ts` for why `live` is the only mode offered here). */
  onWrite(value: string): void;
  /** Open one undo step so an edit is one Ctrl+Z, not one per character. */
  beginEdit?(): void;
  /** The commit boundary — one call per gesture, however the field was left. */
  onEditEnd?(value: string, startValue: string): void;
  /**
   * What makes this field know its grammar: slot decorations, a completion
   * source, a language. Omit it and you get the plain code text box.
   */
  grammar?: CodeFieldGrammar;
  disabled?: boolean;
  placeholder?: string;
  ariaLabel?: string;
  ariaDescribedBy?: string;
  ariaInvalid?: boolean;
  className?: string;
  testId?: string;
  style?: CSSProperties;
  /** Take focus on mount; `'select'` also selects the whole line. */
  autoFocus?: boolean | "select";
  /** With `autoFocus`, put the caret here instead of selecting everything. */
  cursorAt?: number;
  /** With `autoFocus`, select exactly this range — the slot that was clicked, not the whole line. */
  selectRange?: { from: number; to: number };
  /**
   * A lane: several lines, one per thing. Enter inserts a line, Alt+↑/↓
   * move one, Shift+Alt+↓ copies one (all CodeMirror's default keymap);
   * Ctrl/Cmd+Enter is the exit that Enter is for a single line.
   */
  multiline?: boolean;
  /** Pin every line to this height so lines can sit on a host's own rows. */
  lineHeightPx?: number;
  align?: "left" | "right";
  /** Soft-wrap long lines (a viewer), instead of letting them run. */
  wrap?: boolean;
  /** Extra chrome rendered inside the field's frame, positioned by the host's CSS. */
  trailing?: ReactNode;
  /**
   * Enter and Escape both end the gesture by leaving the field (the value is
   * never discarded — Ctrl+Z is the retract). A host that owns its own
   * editing session supplies its own exits instead of the default `leave`.
   */
  onEnter?(): void;
  onEscape?(): void;
  onViewReady?(view: EditorView): void;
  /**
   * Controlled two-way toggle between the pretty RENDERED tree
   * (`grammar.lines`) and the live SOURCE document (CodeMirror) — the "code
   * block overlay" idea: rendered by default, source under the caret. Omit
   * entirely for a field that is always source (the original, and still
   * the right choice for a plain port row with nothing worth a read view).
   * The host owns the state; `CodeField` never flips it on its own.
   */
  mode?: "rendered" | "source";
  /** Used by the optional `CodeFieldModeToggle` sub-component; `CodeField` itself never calls this. */
  onModeChange?(mode: "rendered" | "source"): void;
  /**
   * A rendered row (or the blank space below the last one) was clicked.
   * Only meaningful with `mode` set — the host typically responds by
   * setting `mode="source"` and computing `cursorAt` from `line`/`column`
   * (see `caretGeometry.ts`'s `lineStartOffset`).
   */
  onOpenSource?(line: number, column: number): void;
}

/**
 * The code text box: one line (or a multi-line lane) of text that knows
 * what it is.
 *
 * It is a real CodeMirror document, so highlighting, the completion
 * tooltip, IME, undo and the caret all come from one mature engine rather
 * than a mirror-div. What the field does NOT know is any grammar — that
 * arrives through `grammar`, so a port line, a type alias and a plain label
 * are the same component with different grammars plugged in. Commit
 * semantics are `FieldGesture`'s, unchanged: a field never stops existing
 * with an uncommitted edit.
 *
 * With `mode` set, this is a thin dispatcher: `"rendered"` mounts
 * `CodeFieldRows` over `grammar.lines(value)` and CodeMirror never mounts at
 * all; `"source"` (or `mode` omitted) mounts the live document below. The
 * two never coexist — leaving rendered mode unmounts the row tree exactly
 * as `CodeFieldSourceView` unmounts when rendered mode takes over — so a
 * grammar with no `lines()` still works fine as an always-source field.
 */
export function CodeField(props: CodeFieldProps) {
  const { mode, grammar, value, onOpenSource, ariaLabel, className, testId } = props;
  if (mode === "rendered") {
    return (
      <CodeFieldRows
        lines={grammar?.lines?.(value) ?? []}
        resolveReference={grammar?.resolveReference}
        onOpenSource={onOpenSource}
        className={className}
        testId={testId}
      />
    );
  }
  return <CodeFieldSourceView {...props} ariaLabel={ariaLabel} />;
}

/** Two-button `[Rendered | Source]` switch — the chrome `CodeField`'s `mode` toggle needs, matching how it looks on the field this was extracted from. Entirely optional: a host may drive `mode` from its own UI instead. */
export function CodeFieldModeToggle({
  mode,
  onModeChange,
  labels = { rendered: "UI", source: "Source" },
}: {
  mode: "rendered" | "source";
  onModeChange(mode: "rendered" | "source"): void;
  labels?: { rendered: string; source: string };
}) {
  return (
    <div className="bbox-code-field-toggle" data-slot="code-field-mode-toggle">
      <button type="button" data-active={mode === "rendered" || undefined} onClick={() => onModeChange("rendered")}>
        {labels.rendered}
      </button>
      <button type="button" data-active={mode === "source" || undefined} onClick={() => onModeChange("source")}>
        {labels.source}
      </button>
    </div>
  );
}

function CodeFieldSourceView({
  value,
  onWrite,
  beginEdit,
  onEditEnd,
  grammar,
  disabled = false,
  placeholder,
  ariaLabel,
  ariaDescribedBy,
  ariaInvalid,
  className,
  testId,
  style,
  autoFocus = false,
  cursorAt,
  selectRange,
  multiline = false,
  lineHeightPx,
  align = "left",
  wrap = false,
  trailing,
  onEnter,
  onEscape,
  onViewReady,
}: CodeFieldProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const grammarCompartment = useRef(new Compartment());
  const editableCompartment = useRef(new Compartment());
  const placeholderCompartment = useRef(new Compartment());
  const metricsCompartment = useRef(new Compartment());

  const latest = useRef({
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    disabled,
    multiline,
  });
  latest.current = {
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    disabled,
    multiline,
  };

  const metrics = (): Extension => [
    EditorView.theme({
      ...(lineHeightPx
        ? { ".cm-line": { lineHeight: `${lineHeightPx}px`, height: `${lineHeightPx}px` } }
        : {}),
      ...(align === "right" ? { ".cm-content": { textAlign: "right" } } : {}),
    }),
    ...(wrap ? [EditorView.lineWrapping] : []),
  ];

  const gestureRef = useRef<FieldGesture | null>(null);
  if (!gestureRef.current) {
    gestureRef.current = new FieldGesture(
      {
        write: (next) => latest.current.onWrite(next),
        begin: () => latest.current.beginEdit?.(),
        end: (next, start) => latest.current.onEditEnd?.(next, start),
      },
      "live",
    );
  }
  const gesture = gestureRef.current;

  const leave = (view: EditorView) => {
    view.contentDOM.blur();
    gesture.commit();
  };

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const view = new EditorView({
      state: EditorState.create({
        doc: value,
        extensions: [
          history(),
          // Enter and Escape are the field's exits, handled on the raw event
          // so the keystroke can be STOPPED: once the field closes, the same
          // keydown would otherwise reach a host's own document listener
          // with nothing focused — a canvas host that re-enters editing on
          // Enter, or clears a selection on Escape, would immediately undo
          // the exit. A completion popup gets first refusal — its own
          // keymap runs at a higher precedence and reports when it consumed
          // the key.
          Prec.high(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing) return false;
                if (event.key !== "Enter" && event.key !== "Escape") return false;
                if (completionStatus(target.state) === "active") return false;
                // In a lane a bare Enter is a new line; only the modifier form exits.
                if (
                  event.key === "Enter" &&
                  latest.current.multiline &&
                  !event.ctrlKey &&
                  !event.metaKey
                ) {
                  return false;
                }
                event.preventDefault();
                event.stopPropagation();
                const exit = event.key === "Enter" ? latest.current.onEnter : latest.current.onEscape;
                if (exit) exit();
                else leave(target);
                return true;
              },
            }),
          ),
          // A lane is a small IDE buffer, so the line keys people reach for
          // all work: CodeMirror's own Alt+↑/↓ and Shift+Alt+↑/↓, plus the
          // Ctrl forms for anyone whose window manager eats Alt+arrows.
          keymap.of([
            { key: "Ctrl-ArrowUp", run: moveLineUp },
            { key: "Ctrl-ArrowDown", run: moveLineDown },
            { key: "Ctrl-Shift-ArrowUp", run: copyLineUp },
            { key: "Ctrl-Shift-ArrowDown", run: copyLineDown },
            ...defaultKeymap,
            ...historyKeymap,
          ]),
          syntaxHighlighting(classHighlighter),
          grammarCompartment.current.of(grammar ? grammarExtensions(grammar) : []),
          editableCompartment.current.of(EditorView.editable.of(!disabled)),
          placeholderCompartment.current.of(placeholder ? placeholderExtension(placeholder) : []),
          metricsCompartment.current.of(metrics()),
          // The completion popup is parented to the nearest declared tooltip
          // host (a modal, a canvas layer — anything that must keep the
          // popup inside its own stacking context), else the document body.
          // WHY only `[data-tooltip-host]` and not a specific engine's
          // container class: the field stays host-agnostic — a host opts in
          // by putting the attribute on its own wrapper rather than the
          // field special-casing a canvas library by name.
          tooltips({
            position: "absolute",
            parent: host.closest<HTMLElement>("[data-tooltip-host]") ?? document.body,
          }),
          // One line: a typed or pasted newline is dropped rather than
          // growing the field. A lane keeps its newlines — they are its rows.
          EditorView.inputHandler.of((target, from, to, insertedText) => {
            if (latest.current.multiline || !/[\r\n]/.test(insertedText)) return false;
            const cleaned = insertedText.replace(/[\r\n]+/g, "");
            target.dispatch({
              changes: { from, to, insert: cleaned },
              selection: { anchor: from + cleaned.length },
            });
            return true;
          }),
          EditorView.updateListener.of((update) => {
            if (!update.docChanged) return;
            if (update.transactions.every((tr) => tr.annotation(externalSync))) return;
            const text = update.state.doc.toString();
            gesture.focus(latest.current.value);
            gesture.change(text);
          }),
          EditorView.domEventHandlers({
            focus: () => {
              if (latest.current.disabled) return;
              gesture.focus(latest.current.value);
            },
            // A CodeMirror `contentDOM` can flicker focus during its own
            // mount work; a synchronous commit on the first flicker would
            // end the gesture the instant it began. Believed only once it
            // survives a macrotask.
            blur: () => {
              globalThis.setTimeout(() => {
                const current = viewRef.current;
                if (current && !current.hasFocus) gesture.commit();
              }, 0);
            },
          }),
        ],
      }),
      parent: host,
    });
    viewRef.current = view;
    onViewReady?.(view);
    // Focus now and again on the next frame: a host that is mid-transition
    // (a canvas entering its own editing state) can take focus back after
    // the first attempt, and a field that opened without focus is a dead
    // field.
    let frame = 0;
    if (autoFocus) {
      const take = () => {
        if (view.hasFocus || !viewRef.current) return;
        view.focus();
        const length = view.state.doc.length;
        if (selectRange) {
          const anchor = Math.max(0, Math.min(selectRange.from, length));
          const head = Math.max(anchor, Math.min(selectRange.to, length));
          view.dispatch({ selection: { anchor, head } });
        } else if (cursorAt !== undefined) {
          const anchor = Math.max(0, Math.min(cursorAt, length));
          view.dispatch({ selection: { anchor } });
        } else if (autoFocus === "select") {
          view.dispatch({ selection: { anchor: 0, head: view.state.doc.length } });
        }
      };
      take();
      frame = requestAnimationFrame(take);
    }
    return () => {
      cancelAnimationFrame(frame);
      viewRef.current = null;
      view.destroy();
    };
    // One mount for the field's lifetime; content, grammar and editability
    // flow through compartments and dispatches so a re-render never tears
    // the document down mid-gesture.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The document follows the store whenever nobody is typing in it. Every
  // keystroke round-trips back through `value` (the field's one write
  // policy is `live`), so the equality guard is what keeps this from
  // re-fighting the caret.
  useEffect(() => {
    const view = viewRef.current;
    if (!view || view.state.doc.toString() === value) return;
    if (gesture.isEditing && view.hasFocus) return;
    view.dispatch({
      changes: { from: 0, to: view.state.doc.length, insert: value },
      annotations: externalSync.of(true),
    });
  }, [value, gesture]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: grammarCompartment.current.reconfigure(grammar ? grammarExtensions(grammar) : []),
    });
  }, [grammar]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: editableCompartment.current.reconfigure(EditorView.editable.of(!disabled)),
    });
  }, [disabled]);

  useEffect(() => {
    viewRef.current?.dispatch({ effects: metricsCompartment.current.reconfigure(metrics()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lineHeightPx, align, wrap]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: placeholderCompartment.current.reconfigure(
        placeholder ? placeholderExtension(placeholder) : [],
      ),
    });
  }, [placeholder]);

  // A canvas host typically calls `preventDefault()` on its own pointerdown,
  // so clicking the canvas never fires this field's native blur. A
  // capture-phase listener on `document` is the one place "clicked outside
  // the field" is observable regardless of what swallowed the native event.
  useEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      const host = hostRef.current;
      const view = viewRef.current;
      if (!host || !view || !view.hasFocus) return;
      if (event.target instanceof Node && host.contains(event.target)) return;
      const element =
        event.target instanceof Element ? event.target : (event.target as Node | null)?.parentElement;
      if (element?.closest(".cm-tooltip")) return;
      leave(view);
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    return () => document.removeEventListener("pointerdown", handlePointerDown, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Unmount is an end boundary like any other — the one the browser refuses
  // to report, since no blur fires for a focused element removed from the DOM.
  useEffect(() => () => gesture.commit(), [gesture]);

  return (
    <div
      data-slot="code-field"
      className={`bbox-code-field bbox-code-tokens${className ? ` ${className}` : ""}`}
      ref={hostRef}
      role="textbox"
      aria-label={ariaLabel}
      aria-describedby={ariaDescribedBy}
      aria-invalid={ariaInvalid ? true : undefined}
      aria-disabled={disabled ? true : undefined}
      data-testid={testId}
      style={style}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
    >
      {trailing}
    </div>
  );
}

import { useState, type MouseEvent as ReactMouseEvent } from "react";

import { caretOffsetFromPoint } from "./caretGeometry";
import type { CodeFieldLine, CodeFieldReference } from "./codeGrammar";

/** Sum of a row's own segment text — its rendered line, stitched back together. */
function rowText(line: CodeFieldLine): string {
  return line.segments.map((segment) => segment.text).join("");
}

export interface CodeFieldRowsProps {
  /** `grammar.lines(value)` — the top-level rows. */
  lines: CodeFieldLine[];
  resolveReference?(name: string): CodeFieldReference | null;
  /**
   * A row (or the blank space below the last one) was clicked. Reports the
   * source line and an approximate column within it — `caretOffsetFromPoint`
   * against the row's own rendered spans, same caveat as that function's:
   * exact when a row's segments concatenate back to its raw source
   * spacing, approximate otherwise. Compose with `lineStartOffset` (in
   * `caretGeometry.ts`) against the field's `value` for a flat offset to
   * hand `CodeField`'s `cursorAt`.
   */
  onOpenSource?(line: number, column: number): void;
  className?: string;
  testId?: string;
}

/**
 * The RENDERED half of `CodeField`'s `mode` toggle: `grammar.lines()` painted
 * as bold-name / accent-type / muted-value rows, a reference segment as an
 * underlined link, and a chevron for a reference that can expand in place —
 * the "code block overlay" idea: rendered by default, source only under the
 * caret. `CodeField` mounts this in place of CodeMirror while `mode ===
 * "rendered"`; it never runs alongside the live document.
 */
export function CodeFieldRows({ lines, resolveReference, onOpenSource, className, testId }: CodeFieldRowsProps) {
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(() => new Set());
  const toggle = (path: string) =>
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });

  const last = lines[lines.length - 1];
  return (
    <div
      data-slot="code-field-rows"
      className={`bbox-code-field-rows${className ? ` ${className}` : ""}`}
      data-testid={testId}
      // A click that reaches this container (not caught by a row, a
      // chevron, or a reference link on the way) landed on genuinely empty
      // space below the last row. There is no more specific position than
      // "the end of the last line."
      onClick={(event) => {
        if (event.target !== event.currentTarget || !onOpenSource || !last) return;
        onOpenSource(last.line, rowText(last).length);
      }}
    >
      {lines.map((line) => (
        <CodeFieldRow
          key={line.line}
          line={line}
          path={String(line.line)}
          resolveReference={resolveReference}
          onOpenSource={onOpenSource}
          expandedPaths={expanded}
          togglePath={toggle}
        />
      ))}
    </div>
  );
}

function CodeFieldRow({
  line,
  path,
  resolveReference,
  onOpenSource,
  expandedPaths,
  togglePath,
}: {
  line: CodeFieldLine;
  path: string;
  resolveReference?(name: string): CodeFieldReference | null;
  onOpenSource?(line: number, column: number): void;
  expandedPaths: ReadonlySet<string>;
  togglePath(path: string): void;
}) {
  const referenceIndex = line.segments.findIndex((segment) => segment.isReference);
  const resolved = referenceIndex >= 0 && resolveReference
    ? resolveReference(line.segments[referenceIndex]!.text)
    : null;
  const expandable = Boolean(resolved?.expandLines);
  const isOpen = expandable && expandedPaths.has(path);

  const activateRow = (event: ReactMouseEvent<HTMLElement>) => {
    if (!onOpenSource) return;
    const column = caretOffsetFromPoint(event.currentTarget, event.clientX, event.clientY);
    onOpenSource(line.line, Math.min(column, rowText(line).length));
  };

  const children = isOpen && resolved?.expandLines ? resolved.expandLines() : null;

  return (
    <div className="bbox-code-field-row" data-slot="code-field-row" data-depth={path.split("/").length - 1}>
      <span className="bbox-code-field-row-content" onClick={activateRow}>
        <span
          aria-hidden={expandable ? undefined : true}
          className="bbox-code-field-chevron"
          data-caret-ignore=""
          data-open={isOpen || undefined}
          role={expandable ? "button" : undefined}
          tabIndex={expandable ? 0 : undefined}
          onPointerDown={expandable ? (event) => event.stopPropagation() : undefined}
          onClick={expandable ? (event) => { event.stopPropagation(); togglePath(path); } : undefined}
        >
          {expandable ? (isOpen ? "▾" : "▸") : null}
        </span>
        {line.segments.map((segment, index) => {
          const isResolvedReference = index === referenceIndex && resolved;
          const className = `bbox-code-seg${segment.role ? ` bbox-code-seg--${segment.role}` : ""}${
            isResolvedReference ? ` bbox-code-ref bbox-code-ref--${resolved.kind}` : ""
          }`;
          if (isResolvedReference && resolved.onJump) {
            return (
              <span
                key={index}
                className={className}
                role="button"
                tabIndex={0}
                onPointerDown={(event) => event.stopPropagation()}
                onClick={(event) => { event.stopPropagation(); resolved.onJump!(); }}
                onKeyDown={(event) => {
                  if (event.key !== "Enter" && event.key !== " ") return;
                  event.preventDefault();
                  event.stopPropagation();
                  resolved.onJump!();
                }}
              >
                {segment.text}
              </span>
            );
          }
          return (
            <span key={index} className={className}>
              {segment.text}
            </span>
          );
        })}
      </span>
      {isOpen && children ? (
        <div className="bbox-code-field-preview">
          {children.map((child) => (
            <CodeFieldRow
              key={child.line}
              line={child}
              path={`${path}/${child.line}`}
              resolveReference={resolveReference}
              onOpenSource={onOpenSource}
              expandedPaths={expandedPaths}
              togglePath={togglePath}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

import {
  autocompletion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import { RangeSetBuilder, type Extension } from "@codemirror/state";
import {
  Decoration,
  EditorView,
  WidgetType,
  type DecorationSet,
} from "@codemirror/view";

/** Which named region the caret sits in, and the text CodeMirror would replace on completion. */
export interface CodeFieldSlotAt {
  slot: string;
  start: number;
  end: number;
  query: string;
}

/** One highlighted span, expressed as a CSS class rather than a CodeMirror type. */
export interface CodeFieldDecorationRange {
  from: number;
  to: number;
  className: string;
}

export interface CodeFieldCompletion {
  label: string;
  detail?: string;
  /** CodeMirror's completion `type` — drives the built-in icon set, purely cosmetic. */
  type?: string;
}

export interface CodeFieldCompletionContext {
  text: string;
  pos: number;
  explicit: boolean;
}

export interface CodeFieldCompletionResult {
  /** Where the accepted completion starts replacing text. */
  from: number;
  /** Defaults to the caret. */
  to?: number;
  options: CodeFieldCompletion[];
}

/** One role-tagged run of text within a rendered row — a name, a type, a bit of punctuation. */
export interface CodeFieldSegment {
  text: string;
  /** A CSS-class hook (e.g. `"name"` → `.bbox-code-seg--name`); omit for unstyled text. */
  role?: string;
  /**
   * This segment names something `grammar.resolveReference` can look up.
   * The renderer asks only for segments actually on screen — resolution
   * never runs during `lines()` itself, so a grammar's parse stays cheap
   * even when resolution means a board-wide scan.
   */
  isReference?: boolean;
}

/** One row of the RENDERED-mode tree — `grammar.lines`' unit of output. */
export interface CodeFieldLine {
  /** 0-based index into the document's lines. */
  line: number;
  /** Absolute character offset of the line's own start — what `onOpenSource` reports. */
  lineStart: number;
  /** Nesting depth. 0 for every row `lines()` returns directly; a reference's `expandLines()` returns its own rows at `parentDepth + 1`, applied by the renderer, not stamped here. */
  indent: number;
  segments: CodeFieldSegment[];
}

/** What a reference segment resolves to: a click target, and/or more rows to show in place. */
export interface CodeFieldReference {
  /** A grammar-defined vocabulary word (e.g. `"known"` / `"unknown"` / `"primitive"`) — a styling and behaviour hook, not interpreted by the field itself. */
  kind: string;
  /** Present when clicking the reference should navigate elsewhere instead of (or in addition to) expanding. */
  onJump?(): void;
  /**
   * Present when this reference can expand in place — e.g. a record type's
   * own fields, one level deeper. Called lazily, only while the row is
   * open, and only re-called when the row is toggled shut and open again —
   * so an expensive lookup (a live board scan) runs once per look, not
   * once per keystroke anywhere on the field.
   */
  expandLines?(): CodeFieldLine[] | null;
}

/**
 * What makes a `CodeField` know its grammar. Every hook is optional — the
 * empty grammar `{}` is the plain code text box: a real CodeMirror document,
 * no slots, no completions, no marks. `slotAt` is the one function this
 * whole design rests on: a port line, a `Name = expr` alias, a nested
 * attribute tree are each a new `slotAt` plus a `decorate`/`complete` pair,
 * never a new editor.
 *
 * WHY a declarative object instead of a raw CodeMirror `Extension[]` (what
 * the field this was extracted from originally took): a grammar author
 * should not have to learn `RangeSetBuilder`, `StateField` and the
 * `autocompletion` API just to say "these are my three roles, this is what
 * completes after a colon". `grammarExtensions` below is the one place that
 * translation happens; a grammar that genuinely needs raw CodeMirror machinery
 * (a `StateField`, a widget) can still pass it through `CodeFieldGrammar.language`
 * alongside these hooks — `language` is any `Extension`, not just a lezer parser.
 */
export interface CodeFieldGrammar {
  /** A CodeMirror language/parser extension (e.g. `python()`), or any other raw extension the grammar needs mounted. */
  language?: Extension;
  /** Which slot the caret sits in. Drives `complete`; also useful to a host that wants to know what's under the cursor. */
  slotAt?(text: string, caret: number): CodeFieldSlotAt | null;
  /** Marks to paint over the raw text, recomputed on every document change. */
  decorate?(text: string): CodeFieldDecorationRange[];
  /**
   * One completion source, dispatched by slot. Return `null` (or an empty
   * `options` list) to offer nothing — that is the grammar's call, not the
   * field's: `signatureGrammar` refuses to complete the `name` slot so a
   * free-text label is never interrupted while it is typed.
   */
  complete?(
    slot: CodeFieldSlotAt | null,
    query: string,
    ctx: CodeFieldCompletionContext,
  ): CodeFieldCompletionResult | null;
  /**
   * Live-preview style folding for a lane: a line the caret is NOT on shows
   * at most this many characters, then an ellipsis; the caret's own line
   * always shows in full, and moving onto a folded line unfolds it (the
   * decoration recomputes from the selection). Omit for no folding. Has no
   * visible effect on a single-line field — there is only ever one line,
   * and it always holds the caret.
   */
  foldInactiveLinesAfter?: number;
  /**
   * The RENDERED-mode tree: the source parsed into rows of role-tagged
   * segments (bold name, accent type, muted default…), the "code block
   * overlay" — rendered by default, source only under the caret. Required
   * for `CodeField`'s `mode="rendered"`; a grammar that has no rendered
   * view (the plain code text box) simply omits it, and `mode` has nothing
   * to switch to.
   *
   * Nesting is a grammar concern, not a component one: `lines()` itself
   * only ever returns flat, `indent: 0` rows for the source's own lines —
   * a row that names a known reference nests DEEPER rows by resolving it
   * (`resolveReference(name).expandLines()`), not by the source text's own
   * indentation. That is what lets an attribute tree, a flat port lane and
   * a self-referencing type all share one renderer.
   */
  lines?(text: string): CodeFieldLine[];
  /**
   * What a segment marked `isReference` resolves to. Omit to render every
   * reference as plain text with no click target — the grammar's call, not
   * a default the field guesses at (a "known" judgement usually means a
   * live scan of something outside the field, e.g. a host's own registry).
   */
  resolveReference?(name: string): CodeFieldReference | null;
  /**
   * A short label for the completion badge/pill shown beside an option
   * whose `type` (`CodeFieldCompletion.type`) matches — the kind-pill
   * pattern from the grammar this was extracted from. Return `null`/
   * `undefined` for a type with no badge.
   */
  completionBadge?(type: string): string | null | undefined;
}

function decorationExtension(decorate: NonNullable<CodeFieldGrammar["decorate"]>): Extension {
  return EditorView.decorations.compute(["doc"], (state) => {
    const ranges = decorate(state.doc.toString())
      .filter((range) => range.to > range.from)
      .slice()
      .sort((a, b) => a.from - b.from || a.to - b.to);
    const builder = new RangeSetBuilder<Decoration>();
    for (const range of ranges) {
      builder.add(range.from, range.to, Decoration.mark({ class: range.className }));
    }
    return builder.finish();
  });
}

function completionExtension(grammar: CodeFieldGrammar): Extension {
  const complete = grammar.complete!;
  const slotAt = grammar.slotAt;
  const source = (context: CompletionContext): CompletionResult | null => {
    const text = context.state.doc.toString();
    const slot = slotAt ? slotAt(text, context.pos) : null;
    const result = complete(slot, slot?.query ?? "", {
      text,
      pos: context.pos,
      explicit: context.explicit,
    });
    if (!result || result.options.length === 0) return null;
    return {
      from: result.from,
      to: result.to ?? context.pos,
      options: result.options.map((option) => ({
        label: option.label,
        detail: option.detail,
        type: option.type,
      })),
    };
  };
  if (!grammar.completionBadge) return autocompletion({ override: [source], icons: false });
  const badge = grammar.completionBadge;
  return autocompletion({
    override: [source],
    icons: false,
    tooltipClass: () => "bbox-code-completion",
    addToOptions: [
      {
        position: 20,
        render: (completion) => {
          const label = completion.type ? badge(completion.type) : null;
          if (!label) return null;
          const pill = document.createElement("span");
          pill.className = "bbox-code-completion-pill";
          pill.dataset.kind = completion.type;
          pill.textContent = label;
          return pill;
        },
      },
    ],
  });
}

class CodeFieldEllipsisWidget extends WidgetType {
  override eq(): boolean {
    return true;
  }
  override toDOM(): HTMLElement {
    const span = document.createElement("span");
    span.className = "bbox-code-field-ellipsis";
    span.textContent = "…";
    return span;
  }
  override ignoreEvent(): boolean {
    return false;
  }
}

function foldExtension(maxChars: number): Extension {
  return EditorView.decorations.compute(["doc", "selection"], (state): DecorationSet => {
    const builder = new RangeSetBuilder<Decoration>();
    const active = new Set<number>();
    for (const range of state.selection.ranges) {
      active.add(state.doc.lineAt(range.head).number);
      active.add(state.doc.lineAt(range.anchor).number);
    }
    for (let number = 1; number <= state.doc.lines; number += 1) {
      const line = state.doc.line(number);
      if (active.has(number) || line.length <= maxChars) continue;
      builder.add(
        line.from + maxChars,
        line.to,
        Decoration.replace({ widget: new CodeFieldEllipsisWidget() }),
      );
    }
    return builder.finish();
  });
}

/** Translates a declarative `CodeFieldGrammar` into the CodeMirror extensions `CodeField` mounts. */
export function grammarExtensions(grammar: CodeFieldGrammar): Extension[] {
  const extensions: Extension[] = [];
  if (grammar.language) extensions.push(grammar.language);
  if (grammar.decorate) extensions.push(decorationExtension(grammar.decorate));
  if (grammar.complete) extensions.push(completionExtension(grammar));
  if (grammar.foldInactiveLinesAfter != null) {
    extensions.push(foldExtension(grammar.foldInactiveLinesAfter));
  }
  return extensions;
}

/**
 * The live-commit contract `CodeField` follows.
 *
 * WHY a gesture object instead of "call `onWrite` on change, `onEditEnd` on
 * blur": a text field's edit is a *gesture* with three boundaries — it
 * begins, it produces values, and it ends exactly once — and how the field
 * was left (blur, Enter, Escape, the host unmounting the panel) only
 * decides *when* the gesture ends, never *whether* the value survives. The
 * browser will not tell you about the last one: no `blur` fires for a
 * focused element removed from the DOM, so a naive commit-on-blur field
 * silently drops whatever was typed the instant its panel unmounts. This
 * class is driven from the React lifecycle instead (`CodeField`'s unmount
 * effect calls `commit()`), where that boundary is observable.
 *
 * Two write policies, both loss-free:
 *
 * - `live` — every keystroke writes straight into the caller's store, so
 *   the store is the only copy of the text and there is nothing left to
 *   lose. `CodeField` uses this exclusively (see WHY below).
 * - `exit` — the value is buffered and written once, at the end boundary,
 *   for a write that is genuinely expensive. Still loss-free, because
 *   unmount is itself an end boundary.
 *
 * `begin` fires lazily, on the first keystroke that actually changes the
 * value, so a field that was merely focused leaves no trace in undo
 * history. `end` is the commit boundary a caller can hang a semantic
 * "rename" or a debounced round trip off, without the live write ever
 * having to wait for it.
 */

export type FieldCommitMode = "live" | "exit";

export interface FieldGestureHooks {
  /** Write the value. Per keystroke in `live`, once at the end in `exit`. */
  write(value: string): void;
  /**
   * Open one undoable step. Called lazily — on the first keystroke that
   * really changes the value — so merely focusing a field leaves no trace.
   */
  begin?(): void;
  /** The commit boundary. Fires exactly once per gesture, whatever ended it. */
  end?(value: string, startValue: string): void;
}

export class FieldGesture {
  mode: FieldCommitMode;

  private readonly hooks: FieldGestureHooks;
  private editing = false;
  private began = false;
  private start = "";
  private current = "";

  constructor(hooks: FieldGestureHooks, mode: FieldCommitMode = "live") {
    this.hooks = hooks;
    this.mode = mode;
  }

  get isEditing(): boolean {
    return this.editing;
  }

  get startValue(): string {
    return this.start;
  }

  get value(): string {
    return this.current;
  }

  /** Enter the field. Idempotent: re-entering keeps the original pre-edit value. */
  focus(value: string): void {
    if (this.editing) return;
    this.editing = true;
    this.began = false;
    this.start = value;
    this.current = value;
  }

  /** One keystroke, paste, or IME commit. */
  change(value: string): void {
    if (!this.editing) this.focus(this.current);
    if (value === this.current) return;
    this.current = value;
    if (this.mode !== "live") return;
    this.ensureBegun();
    this.hooks.write(value);
  }

  /**
   * End the gesture and keep the value. Every exit route calls this — blur,
   * Enter, Escape, and the unmount cleanup — so it must stay idempotent.
   */
  commit(): void {
    if (!this.editing) return;
    if (this.mode === "exit" && this.current !== this.start) {
      this.ensureBegun();
      this.hooks.write(this.current);
    }
    const value = this.current;
    const start = this.start;
    this.editing = false;
    this.began = false;
    this.hooks.end?.(value, start);
  }

  private ensureBegun(): void {
    if (this.began) return;
    this.began = true;
    this.hooks.begin?.();
  }
}

/**
 * Grammar-agnostic text-geometry helpers for the "click a rendered row and
 * land in source mode with the caret already there" gesture — the seam
 * `CodeField`'s `mode="rendered"` rows use to compute what `onOpenSource`
 * reports. Pure DOM; no grammar, no host.
 */

/** Absolute character offset of the start of `lineIndex` within `source`. */
export function lineStartOffset(source: string, lineIndex: number): number {
  const lines = source.replace(/\r\n?/g, "\n").split("\n");
  let offset = 0;
  for (let i = 0; i < lineIndex && i < lines.length; i++) offset += lines[i].length + 1;
  return offset;
}

/**
 * How far into `container`'s own text a click at (clientX, clientY) landed —
 * used to map a pixel click on a *rendered* row (built from separate name /
 * punctuation / type spans, not the raw source) back onto an approximate
 * column in that row's raw source line. Exact for the common case where the
 * row was authored with the same single-space `name: type = value` spacing
 * the read view renders; if punctuation was written differently, the mapped
 * column is a reasonable placement, not a guarantee.
 */
export function caretOffsetFromPoint(container: HTMLElement, clientX: number, clientY: number): number {
  const doc = document as Document & {
    caretPositionFromPoint?(x: number, y: number): { offsetNode: Node; offset: number } | null;
  };
  let node: Node | null = null;
  let nodeOffset = 0;
  if (typeof document.caretRangeFromPoint === "function") {
    const range = document.caretRangeFromPoint(clientX, clientY);
    if (range) {
      node = range.startContainer;
      nodeOffset = range.startOffset;
    }
  } else if (typeof doc.caretPositionFromPoint === "function") {
    const pos = doc.caretPositionFromPoint(clientX, clientY);
    if (pos) {
      node = pos.offsetNode;
      nodeOffset = pos.offset;
    }
  }
  if (!node || !container.contains(node)) return container.textContent?.length ?? 0;
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  let offset = 0;
  let current: Node | null;
  while ((current = walker.nextNode())) {
    // Chrome that shares the row but is not part of the source line — a
    // chevron glyph — is marked `data-caret-ignore`; counting it shifted
    // every mapped column one character right of the click.
    if (current.parentElement?.closest("[data-caret-ignore]")) {
      if (current === node) return offset;
      continue;
    }
    if (current === node) return offset + nodeOffset;
    offset += current.textContent?.length ?? 0;
  }
  return offset;
}

/*
 * The code text box. Sized to sit where a plain `<input>` sat — a port row,
 * an inspector field — so a board with nothing typed in code looks
 * unchanged. Colours are bbox-ui's own tokens (see theme.css), so the field
 * follows whatever theme the surrounding kit is painted with.
 */

.bbox-code-field {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  padding: 4px 6px;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  background: var(--color-card);
  color: var(--color-foreground);
  cursor: text;
  overflow: hidden;
}

.bbox-code-field[aria-disabled="true"] {
  opacity: 0.6;
  cursor: default;
}

.bbox-code-field:focus-within {
  border-color: var(--color-primary);
}

.bbox-code-field .cm-editor {
  outline: none;
  background: transparent;
  height: auto;
}

.bbox-code-field .cm-scroller {
  overflow: hidden;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  line-height: 1.4;
}

.bbox-code-field .cm-content {
  padding: 0;
  caret-color: var(--color-primary);
  white-space: nowrap;
}

.bbox-code-field .cm-line {
  padding: 0;
}

.bbox-code-field .cm-placeholder {
  color: var(--color-muted-foreground);
  font-style: normal;
}

.bbox-code-field .cm-selectionBackground,
.bbox-code-field .cm-focused .cm-selectionBackground,
.bbox-code-field ::selection {
  background: color-mix(in srgb, var(--color-primary) 30%, transparent);
}

.bbox-code-field .cm-cursor {
  border-left-color: var(--color-primary);
}

/* Folded lane lines (`grammar.foldInactiveLinesAfter`): a quiet ellipsis,
   not a button — clicking it just moves the caret onto that line, which
   unfolds it. */
.bbox-code-field .bbox-code-field-ellipsis {
  color: var(--color-muted-foreground);
  cursor: text;
}

/* The wrapper a grammar-aware host puts around the field to carry its own
   diagnostics: a passive warning glyph and an accessible help line. Not
   part of CodeField itself — see the `signature` grammar's field wrapper
   for the pattern — but styled from the same sheet so the two ship together. */
.bbox-code-field-frame {
  position: relative;
  display: block;
  min-width: 0;
}

.bbox-code-field-frame[data-error="true"] .bbox-code-field {
  border-color: color-mix(in srgb, var(--bbox-danger) 60%, var(--color-border));
}

.bbox-code-field-frame__warning {
  position: absolute;
  top: 50%;
  right: 6px;
  transform: translateY(-50%);
  color: var(--bbox-warning);
  font-size: 11px;
  line-height: 1;
  pointer-events: none;
}

.bbox-code-field-frame__help {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* The `signature` grammar's three roles: the name carries the ink, the type
 * is an accent-tinted hint, the default is a muted value, and the two
 * glyphs between them are quieter than any of the three. These win over the
 * generic syntax token colours on purpose — a free-text name of three words
 * must not light up as three variable references. */
.bbox-code-field .bbox-sig-name,
.bbox-code-field .bbox-sig-name.tok-variableName {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-field .bbox-sig-type,
.bbox-code-field .bbox-sig-type.tok-variableName {
  color: color-mix(in srgb, var(--color-primary) 55%, var(--color-foreground));
  font-weight: 400;
}

.bbox-code-field .bbox-sig-punct {
  color: var(--color-muted-foreground);
}

.bbox-code-field .bbox-sig-default {
  color: var(--color-foreground);
}

/*
 * RENDERED mode (`CodeField`'s `mode="rendered"`, `CodeFieldRows`): the same
 * three roles as source mode's marks, painted as React children instead of
 * CodeMirror decorations. `.bbox-code-seg--*` mirrors `.bbox-sig-*` above —
 * a grammar that reuses the `signature` role names gets one palette for
 * both modes for free.
 */
.bbox-code-field-rows {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  line-height: 1.6;
  color: var(--color-foreground);
  cursor: text;
}

.bbox-code-field-row {
  display: flex;
  flex-direction: column;
}

.bbox-code-field-row-content {
  display: flex;
  align-items: baseline;
  white-space: pre;
}

.bbox-code-field-chevron {
  display: inline-flex;
  width: 12px;
  flex-shrink: 0;
  color: var(--color-muted-foreground);
  font-size: 9px;
  cursor: default;
}

.bbox-code-field-chevron[role="button"] {
  cursor: pointer;
}

.bbox-code-field-preview {
  margin-left: 12px;
  padding-left: 8px;
  border-left: 1px solid var(--color-border);
}

.bbox-code-seg--name {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-seg--type {
  color: color-mix(in srgb, var(--color-primary) 55%, var(--color-foreground));
}

.bbox-code-seg--default {
  color: var(--color-foreground);
}

.bbox-code-seg--punct {
  color: var(--color-muted-foreground);
}

/* A reference segment: underlined and clickable only once it resolves —
 * `resolveReference` returning `null` (an unknown name) leaves it looking
 * like ordinary accent text, matching source mode's plain `tok-variableName`
 * treatment for the same case. */
.bbox-code-ref[role="button"] {
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}

.bbox-code-ref--unknown {
  color: var(--bbox-danger);
}

/* `CodeFieldModeToggle` — a small [Rendered | Source] switch. */
.bbox-code-field-toggle {
  display: inline-flex;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  overflow: hidden;
}

.bbox-code-field-toggle button {
  padding: 2px 8px;
  border: none;
  background: transparent;
  color: var(--color-muted-foreground);
  font-size: 11px;
  cursor: pointer;
}

.bbox-code-field-toggle button[data-active] {
  background: var(--color-muted);
  color: var(--color-foreground);
}

/* The completion tooltip's kind pill (`CodeFieldGrammar.completionBadge`). */
.bbox-code-completion-pill {
  margin-left: 6px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--color-muted);
  color: var(--color-muted-foreground);
  font-size: 10px;
  line-height: 1.6;
}

/*
 * The one syntax palette for every `CodeField`. `classHighlighter`
 * (`@lezer/highlight`) emits stable `tok-*` classes with no baked-in
 * colour — any grammar that mounts a language (`grammar.language`) gets
 * real syntax highlighting for free, and every field reads the same
 * palette rather than each grammar inventing its own. Colours are bbox-ui's
 * `--color-*` tokens (see theme.css), so this follows the surrounding
 * theme automatically. Optional: a plain-text field (no `grammar.language`)
 * never needs this file.
 */

.bbox-code-tokens .tok-keyword,
.bbox-code-tokens .tok-operatorKeyword,
.bbox-code-tokens .tok-controlKeyword,
.bbox-code-tokens .tok-definitionKeyword,
.bbox-code-tokens .tok-moduleKeyword {
  color: color-mix(in srgb, var(--color-primary) 78%, var(--color-foreground));
  font-weight: 600;
}

.bbox-code-tokens .tok-string,
.bbox-code-tokens .tok-docString,
.bbox-code-tokens .tok-character,
.bbox-code-tokens .tok-attributeValue {
  color: color-mix(in srgb, var(--bbox-success) 62%, var(--color-foreground));
}

.bbox-code-tokens .tok-number,
.bbox-code-tokens .tok-integer,
.bbox-code-tokens .tok-float,
.bbox-code-tokens .tok-bool,
.bbox-code-tokens .tok-atom,
.bbox-code-tokens .tok-null,
.bbox-code-tokens .tok-unit {
  color: color-mix(in srgb, var(--bbox-warning) 58%, var(--color-foreground));
}

.bbox-code-tokens .tok-comment,
.bbox-code-tokens .tok-lineComment,
.bbox-code-tokens .tok-blockComment,
.bbox-code-tokens .tok-meta {
  color: var(--color-muted-foreground);
  font-style: italic;
}

.bbox-code-tokens .tok-typeName,
.bbox-code-tokens .tok-className,
.bbox-code-tokens .tok-namespace {
  color: color-mix(in srgb, var(--color-primary) 55%, var(--color-foreground));
}

/* A bare name is the token a code field most needs to read at a glance as
 * "this references something", so it gets the accent at full strength —
 * unlike every other token's muted mix. */
.bbox-code-tokens .tok-variableName,
.bbox-code-tokens .tok-variableName2,
.bbox-code-tokens .tok-definition,
.bbox-code-tokens .tok-self {
  color: var(--color-primary);
}

.bbox-code-tokens .tok-propertyName,
.bbox-code-tokens .tok-attributeName,
.bbox-code-tokens .tok-labelName {
  color: color-mix(in srgb, var(--bbox-danger) 42%, var(--color-foreground));
}

.bbox-code-tokens .tok-function,
.bbox-code-tokens .tok-macroName {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-tokens .tok-operator,
.bbox-code-tokens .tok-punctuation,
.bbox-code-tokens .tok-separator,
.bbox-code-tokens .tok-bracket {
  color: var(--color-muted-foreground);
}

.bbox-code-tokens .tok-invalid {
  color: var(--bbox-danger);
}
